package com.example; import akka.actor.typed.ActorRef; import akka.actor.typed.Behavior; import akka.actor.typed.javadsl.ActorContext; import akka.actor.typed.javadsl.Behaviors; public class WorkerActor { public interface Command {} public record Process(int number, ActorRef<SupervisorActor.Result> replyTo) implements Command {} public static Behavior<Command> create(String name) { return Behaviors.setup(context -> { return Behaviors.receive(Command.class) .onMessage(Process.class, message -> { context.getLog().info( "{} procesando el numero {}", name, message.number() ); if (message.number() == -1) { context.getLog().error( "{} fallo intencionalmente", name ); throw new RuntimeException( "Fallo simulado en " + name ); } int result = message.number() * message.number(); message.replyTo().tell( new SupervisorActor.Result( name, message.number(), result ) ); return Behaviors.same(); }) .build(); }); } }
